import {ObjectViewer} from '../viewer/object-viewer.js';
import {blueprint,TYPES} from './blueprint.js';
import {shipModel} from './model.js';
import {appliedSurface} from '../hull/applied.js';
import {hullMaterial} from '../hull/material.js';
import {applyShipLighting} from '../credits/ship-lighting.js';
const $=id=>document.getElementById(id);let viewer,plan,buildId=0;
for(const type of TYPES){const o=document.createElement('option');o.value=type;o.textContent=type[0].toUpperCase()+type.slice(1)+' modules';$('part').append(o);}
const params=new URLSearchParams(location.search);if(params.has('seed'))$('seed').value=params.get('seed');
async function rebuild(preserveCamera=false,newSeed=false){if(!viewer)return;const id=++buildId;plan=blueprint($('seed').value);if(newSeed){$('finish').value=plan.appearance.finish;$('roughness').value=plan.appearance.roughness;$('wear').value=plan.service.age;$('part').value='';$('explode').value=0;}$('role').value=plan.role;$('count').value=plan.count;$('countOut').value=plan.count;let hull=null;if($('finish').value==='custom'){try{const data=await appliedSurface();if(id!==buildId)return;hull=hullMaterial(data.maps,data.levels);}catch(e){$('stats').textContent=e.message;return;}}const camera=viewer.camera.position.clone(),target=viewer.controls.target.clone();const model=shipModel(plan,{explode:Number($('explode').value),roughness:Number($('roughness').value),finish:$('finish').value,single:$('part').value,hull,detailSize:256,wear:Number($('wear').value)});const lighting=applyShipLighting(model);lighting.update(48,{x:0,y:0,z:-35});viewer.setObject(model,{disposePrevious:true});if(preserveCamera){viewer.camera.position.copy(camera);viewer.controls.target.copy(target);viewer.controls.update();}else frameShip();$('stats').textContent=`${plan.parts.length} modules · ${plan.family} · ${plan.role} · ${plan.service.registry} · wear ${(Number($('wear').value)*100).toFixed(0)}%`;const url=new URL(location.href);for(const id of ['seed'])url.searchParams.set(id,$(id).value);url.searchParams.delete('role');url.searchParams.delete('count');history.replaceState(null,'',url);}
$('generate').onclick=()=>rebuild(false,true);for(const id of ['part','finish'])$(id).onchange=()=>rebuild();let rebuildTimer;for(const id of ['explode','roughness','wear'])$(id).oninput=()=>{clearTimeout(rebuildTimer);rebuildTimer=setTimeout(()=>rebuild(true),100);};
$('seed').onkeydown=e=>{if(e.key==='Enter')rebuild(false,true);};$('random').onclick=()=>{$('seed').value='AE-'+crypto.getRandomValues(new Uint32Array(1))[0].toString(36).toUpperCase();rebuild(false,true);};
$('rotate').onchange=()=>{if(viewer)viewer.controls.autoRotate=$('rotate').checked;};$('frame').onclick=frameShip;$('exposure').oninput=()=>{if(viewer)viewer.renderer.toneMappingExposure=Number($('exposure').value);};$('light').oninput=()=>{if(viewer){const a=Number($('light').value)*Math.PI/180;viewer.key.position.set(Math.sin(a)*6,4,Math.cos(a)*6);}};
$('reference').onclick=()=>$('referenceDialog').showModal();$('close').onclick=()=>$('referenceDialog').close();$('export').onclick=()=>{if(!plan)return;const url=URL.createObjectURL(new Blob([JSON.stringify(plan,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='aether-ship-blueprint.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function frameShip(){if(!viewer)return;viewer.frame();const d=viewer.camera.position.distanceTo(viewer.controls.target),direction=viewer.camera.position.clone().set(.9,.35,1).normalize();viewer.camera.position.copy(viewer.controls.target).addScaledVector(direction,d);viewer.controls.update();}
function setLighting(){if(!viewer)return;const inspection=$('lighting').value==='inspection';viewer.key.color.set(inspection?0xeaf0f3:0xffeedb);viewer.key.intensity=inspection?2.8:2.2;viewer.rim.intensity=inspection ? .55 : .25;viewer.fill.intensity=inspection ? .65 : .07;}
$('lighting').onchange=setLighting;
try{viewer=await new ObjectViewer().initialize($('viewport'),{studioEnvironment:false});viewer.controls.autoRotate=true;viewer.scene.environmentIntensity=1;viewer.renderer.toneMappingExposure=1.1;$('exposure').value=1.1;setLighting();rebuild(false,true);}catch(e){$('error').hidden=false;$('error').textContent=e.message;$('stats').textContent='WebGPU initialization failed';viewer?.dispose();}
window.addEventListener('pagehide',()=>{buildId++;clearTimeout(rebuildTimer);viewer?.dispose();viewer=null;});
